void Qsort(int A[],int L,int R)
{
    if (L>=R)
        return;
    int pivot, i=L, j=R;
    pivot=A[L];
    while (i<j)
    {
        while (i<j && A[j]>=pivot) j--;
        while (i<j && A[i]<=pivot) i++;
        if (i<j)
            swap(A[i], A[j]);                   // A[j]<pivot，A[i]>pivot，交换
    }
    swap(A[L], A[i]);                           // 将基准值放入他的最终位置
    Qsort(A, L, i-1);
    Qsort(A, i+1, R);
}
