// 使用 BFS 计算无权图的单源最短路径
void BFS_ShortestPath(MGraph G, int start)
{
    int queue[MAXV];
    int visited[MAXV]={false};
    int dist[MAXV], int path[MAXV];
    int front = 0, rear = 0;
    // 1.初始化
    for (int i = 0; i < G.numVertices; i++)
    {
        dist[i] = INT_MAX;
        path[i] = -1;
    }
    // 2.将源点入队
    dist[start] = 0;
    queue[rear++] = start;                      // 源点入队
    visited[start] = true;
    // 3.当队列不为空时，循环执行
    while (front < rear)                        // 队列不为空
    {
        // 3-a.队头元素 u 出队
        int u = queue[front++];                 // 队头元素出队
        // 3-b.遍历 u 的所有相邻结点 v，如果 v 尚未入队过则将 v 入队并更新距离
        for (int v = 0; v < G.numVertices; v++)
            if (visited[v] == false && G.Edge[u][v] == 1)
            {
                dist[v] = dist[u] + 1;
                path[v] = u;
                queue[rear++] = v;              // 新访问的顶点入队
                visited[v] = true;
            }
    }
    根据 dist 数组输出长度，根据 path 数组输出路径
}

