int Dijkstra(MGraph G, int start)
{
    int dist[MAXV], int path[MAXV];
    // 1. 初始化
    bool visited[MAXV] = {false};               // 记录顶点是否已确定
    for (int i = 0; i < G.numVertices; i++)
    {
        dist[i] = INT_MAX;
        path[i] = -1;
    }
    // 将起点到自身的距离设为 0
    dist[start] = 0;
    // 2. 循环 G.numVertices 次，每次找到一个最短路径并更新其他顶点
    for (int i = 0; i < G.numVertices; i++)
    {
        // a. 在未访问的顶点中，找到距离起点最近的顶点 u
        // 在第一次循环中，由于 dist[start] = 0，u 会被自然地赋值为 start
        int u = -1;
        int min_dist = INT_MAX;
        for (int j = 0; j < G.numVertices; j++)
        {
            if (visited[j] == false && dist[j] < min_dist)
            {
                min_dist = dist[j];
                u = j;
            }
        }
        if (u == -1) return -1;                 // 如果找不到下一个顶点说明是非连通图
        // b. 标记 u 为已访问
        visited[u] = true;
        // c. 松弛操作：更新从 u 出发能够到达的所有未访问顶点的距离
        for (int v = 0; v < G.numVertices; v++)
        {
            // 条件：v 未被访问过，且存在从 u 到 v 的边，
            // 并且通过 u 到达 v 的路径比当前记录的路径更短
            if (!visited[v] && G.Edge[u][v] != 0 && dist[u] + G.Edge[u][v] < dist[v])
            {
                // 更新 v 的最短距离和前驱结点
                dist[v] = dist[u] + G.Edge[u][v];
                path[v] = u;
            }
        }
    }
    根据 dist 数组输出长度，根据 path 数组输出路径
    return 0;
}

