    不妨假设所有的边已经在数组 edges 中，边的数量为 m
    void Qsort(edges[], 0, G.numEdges-1);
    // 2.初始化并查集，初始时所有顶点属于不同集合。
    for (int i = 0; i < G.numVertices; i++)
        parent[i] = i;
    // 3.循环，直到选出 n-1 条不成环的边
    for (int i = 0; i < m; i++)
    {
        // 3-a. 对于还未处理的最小边，使用并查集判断该边的两个端点分别属于哪个集合
        int rootU = Find(edges[i].u);
        int rootV = Find(edges[i].v);
        // 3-b. 如果不属于同一个集合则选择该边、合并这两个集合
        if (rootU != rootV)
        {
            Union(rootU, rootV);
            将该边加入到生成树中
            count++;
            if (count == G.numVertices-1) break; // 已选择 n-1 条边
        }
    }
    输出最小生成树
}

void TopoSort(ALGraph G)
{
    int indegree[MAXV] = {0};
    // 计算每个顶点的入度
    for (int i = 0; i < G.numVertices; i++)
    {
        ArcNode *p = G.VerticesList[i].first;
        while (p!=NULL)
        {
            indegree[p->adjvex]++;
            p = p->next;
        }
    }
    // 将所有入度为0的顶点入队
    int queue[MAXV], front = 0, rear = 0;
    for (int i = 0; i < G.numVertices; i++)
        if (indegree[i] == 0)
            queue[rear++] = i;
    while (front < rear)
    {
        int u = queue[front++];
        输出顶点u
        // 此处可判断是否只有一个顶点可选，即front+1==rear
        for (ArcNode *p = G.VerticesList[u].first; p != NULL; p = p->next)
        {
            int v = p->adjvex;
            if (--indegree[v] == 0)
                queue[rear++] = v;
        }
    }
    if (rear < G.numVertices)
        拓扑序列不存在，该有向图存在环
}

void TopoSort(MGraph G)
{
    int indegree[MAXV] = {0};
    // 计算每个顶点的入度
    for (int i = 0; i < G.numVertices; i++)
        for (int j = 0; j < G.numVertices; j++)
            if (G.Edge[i][j] != 0)              // 存在边 i→j
                indegree[j]++;
    // 将所有入度为0的顶点入队
    int queue[MAXV], front = 0, rear = 0;
    for (int i = 0; i < G.numVertices; i++)
        if (indegree[i] == 0)
            queue[rear++] = i;
    while (front < rear)
    {
        int u = queue[front++];
        输出顶点 u
        // 此处可判断是否存在唯一拓扑序列（front+1==rear）
        for (int v = 0; v < G.numVertices; v++)
        {
            if (G.Edge[u][v] != 0)
            {
                if (--indegree[v] == 0)
                    queue[rear++] = v;
            }
        }
    }
    if (rear < G.numVertices)
        拓扑序列不存在，该图存在环
}

void CriticalPath(ALGraph G)
{
    int indegree[MAXV] = {0};                   // 存储每个顶点的入度
    int ve[MAXV] = {0};                         // 各顶点最早开始时间
    int vl[MAXV];                               // 各顶点最迟开始时间
    int topo[MAXV];                             // 存储拓扑排序序列
    int front = 0, rear = 0;
    // 第一步：统计入度
    for (int i = 0; i < G.numVertices; i++)
    {
        ArcNode *p = G.VerticesList[i].first;
        while (p != NULL)
        {
            indegree[p->adjvex]++;
            p = p->next;
        }
    }
    // 第二步：拓扑排序，并计算每个顶点的最早发生时间 ve
    for (int i = 0; i < G.numVertices; i++)
        if (indegree[i] == 0)
            topo[rear++] = i;
    while (front < rear)
    {
        int u = topo[front++];
        ArcNode *p = G.VerticesList[u].first;
        while (p != NULL)
        {
            int v = p->adjvex;
            if (--indegree[v] == 0)
                topo[rear++] = v;
            // 更新 ve 值
            if (ve[u] + p->weight > ve[v])
                ve[v] = ve[u] + p->weight;
            p = p->next;
        }
    }
    // 如果 rear < G.numVertices，图中有环，不存在关键路径
    if (rear < G.numVertices)
    {
        输出：图中存在环
        return;
    }
    // 第三步：初始化 vl 数组
    for (int i = 0; i < G.numVertices; i++)
        vl[i] = ve[G.numVertices - 1];          // 默认项目总工期
    // 第四步：逆拓扑序更新 vl 值
    for (int i = G.numVertices - 1; i >= 0; i--)
    {
        int u = topo[i];
        ArcNode *p = G.VerticesList[u].first;
        while (p != NULL)
        {
            int v = p->adjvex;
            if (vl[v] - p->weight < vl[u])
                vl[u] = vl[v] - p->weight;
            p = p->next;
        }
    }
    // 第五步：输出关键活动
    for (int u = 0; u < G.numVertices; u++)
    {
        ArcNode *p = G.VerticesList[u].first;
        while (p != NULL)
        {
            int v = p->adjvex;
            int e = ve[u];
            int l = vl[v] - p->weight;
            if (e == l)
                输出活动<u,v>是关键活动
            p = p->next;
        }
    }
}

